  "風采鈴": {"background": "原受天蝶盟指使接近素還真，卻在相處中動了真情。她與素還真的感情，以及與兒子素續緣的聚散，是早期正劇的重要支線。", "items": ["三青", "碧血龍珠"], "skills": ["擅丹青"], "base": "不夜天含願台", "sayings": [{"kind": "詩詞", "text": "朱雀揮灑三波水　丹青真假分不清 相見時難別亦難　東風無力百花殘 春蠶到死絲方盡　蠟炬成灰淚始乾"}]},
  "吞佛童子": {"background": "異度魔界派來開啟赦道的戰將，曾受聖劍抑制魔性，顯露一劍封禪的人格。與一步蓮華的交鋒，也使他的立場逐漸轉變。", "skills": ["魔燄燼土", "魔之燄", "風火雷擊", "紅蓮吞日"], "items": ["殺誡", "朱厭", "魔之劍"], "identity": "異度魔界先鋒戰神", "base": "火焰魔城"},
