  "慕少艾": {"background": "醫術出眾的藥師，曾隱於琉璃仙境之下。重入江湖後協助正道抵禦異度魔界，即使在險境也常以玩笑自解。", "skills": ["平川定海", "鴻飛冥冥", "賦雅風流", "神引流針"], "items": ["煙斗", "追影"], "identity": "武林三大神醫之一", "base": "峴匿迷谷、琉璃仙境", "sayings": [{"kind": "詩詞", "text": "少年無端愛風流，老來閒賦萬事休。 萬丈勳名孤身外，百世經緯一樽中。"}, {"kind": "口頭禪", "text": "呼呼"}]},
  "綺羅生": {"background": "奇花八部的獸花，也是武道內七修之一。曾以江山快手之名挑戰各路刀客，後因一樁舊怨封刀，以江中畫舫為居。", "skills": ["江山逆斬‧斷", "刀飲江山", "江山捉影‧破", "江山覷影‧斷"], "items": ["江山豔刀", "黑月之淚", "雪璞扇", "月之畫舫"], "identity": "武道七修之「江山快手」、奇花八部之「獸花」", "base": "玉陽江", "sayings": [{"kind": "詩詞", "text": "百代繁華一朝都，誰非過客； 千秋明月吹角寒，花是主人。、身有八千事，寄與古錦織，一絲不成秀，千縷捋成詩。"}]},
  "原無鄉": {"background": "道真一脈的南修真，與倦收天齊名。雙手由銀驃玄解所化，可因應戰局轉為刀、劍、盾或爪。", "skills": ["一晌貪歡", "一卸乾坤", "元無三式"], "items": ["銀驃玄解"], "identity": "銀驃當家、南修真", "base": "煙雨斜陽", "sayings": [{"kind": "詩詞", "text": "嘯傲八表域中，獨騁威雄，慣玄影無蹤，任太虛，蕭瑟鳴風。"}, {"kind": "名言", "text": "魔人並不可懼，心魔才是難題。"}]},
  "倦收天": {"background": "道真一脈的北芳秀，自創九陽天訣。偏愛在永旭之巔觀日出，並與南修真原無鄉並肩面對道門舊事。", "skills": ["九陽天訣"], "items": ["天鞘晨曦(名劍金鋒)", "北斗指引", "極光劍一"], "identity": "天地人三脈之一", "base": "永旭之巔", "sayings": [{"kind": "詩詞", "text": "江天一色無纖塵，魚龍潛躍觀道身。 天人焉有兩般義？道不虛行只在人。"}]},
  "意琦行": {"background": "武道七修的重要人物，擅劍且行事獨立。他早年在叫喚淵藪一戰留下的紅爐點雪餘勁，亦成為劇中辨識其劍法的一筆。", "skills": ["紅爐點雪", "劍睨千秋塵", "劍弭八方", "初心之劍"], "items": ["澡雪劍", "春秋闋", "天意", "點雪", "神霄琦瑞(巨魔神)"], "identity": "武道七修第一人、天地人三脈之一、開陽武曲星", "base": "叫喚淵藪、通天道、指月山瀑、恆山九星台", "sayings": [{"kind": "詩詞", "text": "❶古豈無人，孤標凌雲誰與朋；高塚笑臥，天下澡雪任琦行。"}, {"kind": "詩詞", "text": "❷古豈無人，孤標凌雲誰與朋；高塚笑臥，春秋一闋任琦行。"}, {"kind": "詩詞", "text": "❸古豈無人，意行千里論春秋；山月笑臥，孤標塵外一劍宿。"}]},
  "君奉天": {"background": "德風古道的法儒，重視規矩與公義。曾鎮守昊正五道，後因單鋒罪者一案再次介入江湖。", "skills": ["嶷如秋山‧令出不返‧天地正法", "天聖罡風", "天法無易", "天地無量"], "items": ["正法", "至衡律典", "仙海靈獸圖"], "identity": "昊正五道之「法儒無私」、雲海仙門少主", "base": "昊法修堂", "sayings": [{"kind": "詩詞", "text": "❶正天地所不正，判黑白所不判，犯人鬼所不犯，破日月所不破。儒法、無情，法儒、無私。"}, {"kind": "詩詞", "text": "❷江聲嶽色， 萬仞崢嶸劍長歌， 青冥浩蕩， 天涯孤舠盡折蒿， 雲闢千層巔， 還看一山高。"}]},
