  "地冥": {"background": "九天玄尊所選的玄黃三乘之一，身分多變，容貌又與天跡相似。他常用不同身分布置局勢，讓對手難以辨認其真正意圖。", "skills": ["地擁獨日", "地煞王令", "地刃冥斷", "天風寄影"], "items": ["神泣", "鬼諦星宿劫", "殉道之眼"], "identity": "天地人玄黃三乘之一", "base": "冥日之淵、惡魔眼淚、永夜劇場、血闇漩溟", "sayings": [{"kind": "詩詞", "text": "酆都路、殉道行，梟雄葬荒骨。 天無聲、地無語，凡塵豈視人中末。 末日，無神論。"}]},
  "天跡": {"background": "玄黃三乘之一，隱居仙腳之巔仍留意武林動向。行事看似隨興，關鍵時刻卻善於衡量局勢、作出決斷。", "skills": ["驚天動地第一掌", "魁星踢斗", "天行日月", "天罡玉旨"], "items": ["神諭", "醉逍遙(拂塵)", "逍遙遊"], "identity": "天地人玄黃三乘之一、玉逍遙", "base": "仙腳、雲漢仙閣、蒼崖雲樹", "sayings": [{"kind": "詩詞", "text": "❶擊冥霄，闢晴曌，萬里卓然乘雲濤；天有行，地無跡，千秋怎堪一劍掃，神光毓逍遙。"}, {"kind": "詩詞", "text": "❷夙風寒，明月勾，豪傑照古城；天有行，地無跡，千秋怎堪一劍掃，神毓逍遙。"}, {"kind": "詩詞", "text": "❸仙衣眠雲碧嵐袍，一襟瀟灑，兩袖飄飄。玉墨舒心春醞瓢，行也逍遙，坐也逍遙。"}]},
  "玉離經": {"background": "接掌德風古道後，須同時協調儒門內部並應對外患。待人溫和，處理門務卻相當審慎。", "skills": ["玉宇八風", "逆風行", "曜宇玉風", "憾宇儒風"], "items": ["玄景天懷"], "identity": "德風古道主事", "base": "粹心殿", "sayings": [{"kind": "詩詞", "text": "離一己之知，經萬眾之義，辨古今之思，志聖賢之期。"}]},
  "莫召奴": {"background": "因不滿鬼祭而攜藏有文詔的國寶離開東瀛，來到中原後居於心築情巢。後因朋友情義，與素還真等人一同應對武林危局。", "skills": ["似是而非", "心劍", "柔和雲蹤步", "乾坤之動"], "items": ["折扇"], "identity": "王者之路中的「無形」、五方主星之「南朱雀」", "base": "心築情巢", "sayings": [{"kind": "詩詞", "text": "有心無心，心在人間；多情薄情，情繫江湖。"}]},
