  "棄天帝": {"background": "異度魔界的創始者，藉聖魔元胎與神柱的力量降臨苦境。厭惡世人自相殘害，卻以摧毀神州回應這份厭惡。", "skills": ["逆返魔源", "神之燄", "神之嵐", "神之渦"], "identity": "異度魔界創始者", "base": "天魔池", "sayings": [{"kind": "台詞", "text": "人間，又污穢了。", "source": "https://www.youtube.com/watch?v=NzZVDvsP_QM"}]},
  "默狩": {"background": "寡言的獵手，曾與雪蛾天驕現身青埂冷峰，打算毀去赭杉軍與白忘機的軀體，因伏龍出手而未能得逞。", "skills": ["默流弒"], "items": ["刀"]},
  "灋栖心": {"background": "藏門馝婆，為灋雲從之弟，因長年病痛與詛咒被囚於寂寞塔。性情有時天真，有時又顯得極有城府。", "identity": "藏門少主", "base": "寂寞塔", "sayings": [{"kind": "口頭禪", "text": "誰為吾刻碑？"}]},
  "素還真": {"background": "自《霹靂金光》登場後，屢以化身和謀略介入武林危局。以琉璃仙境為重要據點，亦擅醫理與陣法。", "skills": ["明聖劍法", "玄子神功", "龍氣劍", "石破天驚混元掌"], "items": ["孔雀劍", "紫虹神劍", "龍骨聖刀", "琉璃辟邪珠", "神農醫譜"], "identity": "日月星三才子之日才子、紫龍天、天虎八將之一、造世七俠之一、五方主星之中麒麟", "base": "翠環山、黃山、百棺機密門、九死一生洞、琉璃仙境、六十四個求生站、雲塵盦、千雲谷推松巖", "sayings": [{"kind": "詩詞", "text": "半神半聖亦半仙，全儒全道是全賢；\n腦中真書藏萬卷，掌握文武半邊天。"}]},
  "一頁書": {"background": "號梵天，佛門高僧，雲渡山是其重要據點。與素還真常共同解危，但面對邪勢時行事更直接果決。", "skills": ["千里碎腦神音（天龍吼）", "大梵聖掌", "九梵神印", "八部龍神火"], "items": ["如是我斬", "三恆曌世", "天君絲", "玉錦囊", "金翼大鵬鳥", "明聖天書"], "identity": "梵天、創世者、末世聖傳「烈天真宗」、人之最", "base": "雲渡山、連天峰迴元洞", "sayings": [{"kind": "詩詞", "text": "世事如棋，乾坤莫測，笑盡英雄。"}]},
  "葉小釵": {"background": "從侍童出身走到刀劍雙修的境地，平日寡言，卻看重承諾。白髮、傷疤和背負刀劍是其標誌。", "skills": ["活殺留聲", "隔紙斷樹", "雪花蓋頂", "般若懺"], "items": ["陰鳳刀", "紫凰劍", "掛日刀", "魔瞳之戒"], "identity": "佛教傳人、造世七俠之一、古武族太武", "base": "天南山、半駝廢小屋、琉璃仙境、天機湖、水月兩忘軒、鏡湖仙雲、雕神古魄", "sayings": [{"kind": "詩詞", "text": "征衣紅塵化雲煙，江湖落拓不知年，\n劍痴刀狂世紛云，今將衣缽卸雙肩；\n踏盡千山無人識，當初枉受盛名牽，\n東風吹醒英雄夢，笑對青山萬重天。\n愛落紅塵心已死，持刀抱劍了一生。"}]},
  "黑白郎君": {"background": "本名南宮恨，愛向成名武者挑戰，不惜把自己的生死也押在較量上。黑白分明的外貌和幽靈馬車尤為醒目。", "skills": ["收化運發", "一氣化九百", "五絕神功", "離合並流"], "items": ["幽靈魔刀", "陰陽扇", "日月珍珠冠", "幽靈馬車"], "sayings": [{"kind": "詩詞", "text": "傲笑天地間，黑白兩不分；\n馬車幽靈影，瀟灑一郎君。"}, {"kind": "名言", "text": "別人的失敗就是我的快樂！"}]},
  "風之痕": {"background": "出身魔界的傳奇劍客，追求劍術極致。與憶秋年是知己也是論劍對手，並將不同風格的劍術傳給兩位劍少。", "skills": ["魔流劍", "風之痕"], "items": ["魔流劍", "絕代之狂", "叱風劍", "風之痕補遺劍譜"], "base": "孤獨峰、竹林小屋、千丘遠", "sayings": [{"kind": "詩詞", "text": "昂首千丘遠，嘯傲風間；\n堪尋敵手共論劍，高處不勝寒。"}]},
  "亂世狂刀": {"background": "以獅頭寶刀和狂龍八斬法成名，性情豪烈，對慕容嬋用情深重。後得道尊相助，成為道教傳人。", "skills": ["狂龍八斬法"], "items": ["獅頭寶刀", "四孔簫"], "identity": "道教傳人", "base": "悟劍亭、楓橋、鏡花水月臺、苦竹籬", "sayings": [{"kind": "詩詞", "preserveLineBreaks": true, "text": "一簫一劍平生意，負盡狂名十五年。\n簫中弦音藏柔情，劍下腥血寄恨仇；\n來何洶湧須揮劍，去向纏綿可付簫。\n九輪異譜再登場\n沉思十五年中事，才也縱橫，淚也縱橫，雙負簫心與劍名。"}, {"kind": "口頭禪", "text": "慕容嬋啊∼"}]},
  "暴雨心奴": {"background": "精研祆撒教邪法，曾以十八地獄陣設局圍殺九千勝與最光陰。雨水在他眼中有特殊意義，也與其行事相呼應。", "skills": ["血雨橫天", "焚焰鬼心斬", "魘流斬風雲", "焰鐮破殺"], "items": ["戰鐮"], "identity": "烈劍宗少主、祆撒大護法、原名「烈霏」", "base": "畸零雨地"},
  "最光陰": {"background": "北狗的真實身分。曾為替九千勝求得生機與時間城立約、守護時間樹；歲月磨去部分記憶後，他再度走入江湖。", "skills": ["掠影擊", "掠影化", "掠影破", "時光渡千輪"], "items": ["嘸狗利", "白毛狗尾巴"], "sayings": [{"kind": "詩詞", "text": "蹉跎錯，消磨過，最是光陰化浮沫。"}]},
  "香獨秀": {"background": "集境蕪園樓主，曾任天府院殿將。劍術出眾，卻也因潔癖與不在乎旁人目光，經常讓同伴哭笑不得。", "items": ["不群之芳"], "skills": ["劍術"], "identity": "蕪園樓主", "base": "蕪園", "sayings": [{"kind": "詩詞", "text": "浮名本是身外物，不著方寸也風流。"}, {"kind": "口頭禪", "text": "虛名，一切都是虛名，浮雲而已。"}]},
  "戢武王": {"background": "殺戮碎島之主，因在婆羅塹擊退火宅佛獄軍隊而廣受擁戴。掌權後仍追查雅狄王的往事。", "skills": ["玄黃廢世", "淹世雪鴻", "寰宇盡廢", "太初一擊"], "items": ["或天戟", "碎島玄舸"], "identity": "殺戮碎島之主", "sayings": [{"kind": "詩詞", "text": "太初之殺，戢武；混沌之戰(戮)，弭兵。"}]},
  "素續緣": {"background": "素還真與風采鈴之子，自幼與雙親分離，曾以天下第一、不知名等身分行走江湖。歷經變故後以醫術濟人。", "skills": ["素續緣： 明心聖火", "萬鼓戰聲", "五形納一", "仙子過橋上瑤台"], "items": ["羽毛扇", "潛龍神戟", "七星佈邪圖", "火輪邪衣"], "identity": "九陽神童、魔域命使、造世七俠、七彩雲天主持", "base": "法佛院、天下第一境、七彩雲天、聖龍口、齊天殿、雲塵盦", "sayings": [{"kind": "詩詞", "text": "廣四海、遊九洲，風遠白雲秋； 立蒼茫、騁遠志，徜徉天地意。"}]},
  "公孫月": {"background": "常作男裝打扮，能看穿人心弱點，善於在局勢未明時周旋。與陰川蝴蝶君的交情是她的重要故事線。", "skills": ["血零丹楓", "九陰斷魂指"], "base": "浮光掠影", "sayings": [{"kind": "詩詞", "text": "掛劍樂不問，江湖山水深，\n靈山忘情月，天涯宦遊人。"}]},
