  "黑衣劍少": {"background": "魔劍道太子，與白衣劍少同門。相比兄長的沉著，他出劍更剛猛，性情也更好勝。", "skills": ["魔流劍", "雙劍並流", "妖刀訣"], "items": ["夜叉劍", "拜邪刀", "波旬劍"], "identity": "魔劍道太子、魔劍道魔皇、妖刀界少主、太荒神決六聖護之一", "base": "魔劍道太子殿、妖刀界、思動即舍、陰司鬼池、千丘遠", "sayings": [{"kind": "詩詞", "text": "暴雨挾狂風，幽靈影未動，\n聞者自喪膽，鬼神劍下亡。"}, {"kind": "口頭禪", "text": "痛快∼"}]},
  "歐陽上智": {"background": "素還真在早期正劇的重要對手，藉收攏武林高手與義子建立歐陽世家的勢力。所倚重的不只是武力，更是操弄人心與局勢。", "skills": ["三泰陰指", "破世陰字"], "items": ["忘年之劍", "歐陽世家家譜"], "identity": "歐陽世家領導者、武林至尊", "base": "無極殿、流亡島", "sayings": [{"kind": "名言", "text": "生，要享受自己雙手所創下的成果； 死，要死在自己雙手所持的利刃下。"}]},
  "奇跡影法師": {"background": "鏡界動亂背後的策劃者，行蹤隱密。善以皮影與傀儡術布局，曾與梅林知者交手後銷聲匿跡。", "skills": ["百影殺生戲", "皮影殺人法", "傀儡七尸符"], "items": ["不朽奇跡", "靈魂之波", "鏡球"], "base": "黑宮", "sayings": [{"kind": "詩詞", "text": "笳鼓新聲奏不停，重重黑幕演諸伶。憑空射電成樓閣，妙景臨機映鏡屏。弄假成真皆幻相，以虛為實亦精靈。叮嚀海外觀奇客，莫訝逢場事渺冥。"}]},
